package com.ivonix.pulse.ontology.domain;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.util.*;
@Service public class EnergyService extends DomainDataService { public EnergyService(JdbcTemplate j){super(j,"energy_data",Set.of("power_output","battery_voltage","battery_current","state_of_charge"));} public DomainDiagnosticResult diagnose(UUID d,UUID o){var x=latest(d,o,1);if(!x.isEmpty()){double s=number(x.get(0),"state_of_charge"),v=number(x.get(0),"battery_voltage");if(!Double.isNaN(s)&&s<15)return new DomainDiagnosticResult("energy","Low state of charge",.88,List.of("Check charging source","Review battery health"));if(!Double.isNaN(v)&&v<10)return new DomainDiagnosticResult("energy","Low battery voltage",.90,List.of("Inspect battery","Check power bus"));}return new DomainDiagnosticResult("energy","No immediate rule-based fault",.10,List.of("Continue monitoring"));}}